  Widget _buildSidebarItem({
    required String numStr,
    required String label,
    required int sectionIndex,
    required GlobalKey targetKey,
  }) {
    final bool isActive = _activeSectionIndex == sectionIndex;
    return GestureDetector(
      onTap: () => _scrollToSection(targetKey, sectionIndex),
      child: Container(
        color: Colors.transparent, // expand hit-test area
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              numStr,
              style: GoogleFonts.jetBrainsMono(
                fontSize: 12,
                fontWeight: FontWeight.w700,
                color: isActive ? AppColors.primary : AppColors.onSurfaceMuted.withOpacity(0.5),
                letterSpacing: 1.0,
              ),
            ),
            const SizedBox(height: 4),
            Text(
              label,
              style: GoogleFonts.inter(
                fontSize: 18,
                fontWeight: isActive ? FontWeight.bold : FontWeight.normal,
                color: isActive ? AppColors.primary : AppColors.onSurface,
              ),
            ),
          ],
        ),
      ),
    );
  }

