  // Signature canvas builder
  Widget _buildSignaturePad() {
    return Stack(
      key: _sigPadKey,
      children: [
        // Background watermarked Seal label
        Center(
          child: Opacity(
            opacity: 0.04,
            child: Text(
              'iUnity Seal',
              style: GoogleFonts.inter(
                fontSize: 24,
                fontWeight: FontWeight.w900,
                color: AppColors.primary,
                letterSpacing: 2,
              ),
            ),
          ),
        ),
        // Drawing interface
        GestureDetector(
          onPanStart: (details) {
            final box = _sigPadKey.currentContext?.findRenderObject() as RenderBox?;
            if (box != null) {
              setState(() {
                _signaturePoints.add(box.globalToLocal(details.globalPosition));
              });
            }
          },
          onPanUpdate: (details) {
            final box = _sigPadKey.currentContext?.findRenderObject() as RenderBox?;
            if (box != null) {
              setState(() {
                _signaturePoints.add(box.globalToLocal(details.globalPosition));
              });
            }
          },
          onPanEnd: (details) {
            setState(() {
              _signaturePoints.add(null);
            });
          },
          child: CustomPaint(
            painter: _SignaturePainter(points: _signaturePoints),
            size: Size.infinite,
          ),
        ),
        // Clear text button overlay
        Positioned(
          top: 6,
          right: 8,
          child: InkWell(
            onTap: () {
              setState(() {
                _signaturePoints.clear();
              });
            },
            child: Padding(
              padding: const EdgeInsets.all(4.0),
              child: Text(
                'CLEAR',
                style: GoogleFonts.jetBrainsMono(
                  fontSize: 10,
                  fontWeight: FontWeight.w800,
                  color: AppColors.primary.withOpacity(0.6),
                  letterSpacing: 0.5,
                ),
              ),
            ),
          ),
        ),
      ],
    );
  }
